select from sys_user_notice un inner join sys_notice n on n.id = un.notice_id where un.user_id = #{userId}
and un.is_read = 0
order by n.publish_time desc, n.id desc

select user_id userId, count(*) unreadCount from sys_user_notice where is_read = 0 and user_id in
#{userId}
group by user_id
